const localFlag=key=>{try{return localStorage.getItem('qingjian:'+key)==='true';}catch{return false;}};
const rememberFlag=(key,value)=>{try{localStorage.setItem('qingjian:'+key,String(value));}catch{}};

const state={config:null,pages:[],route:'home',page:null,dirty:false,saving:null,saveError:'',editSeq:0,query:'',tag:'',sort:'updated',favorites:false,expanded:new Set(),selectionWorkspace:'',selectingPages:false,selectedPages:new Set(),trashSelected:new Set(),purgePlan:null,sidebar:false,sidebarCollapsed:localFlag('sidebarCollapsed'),readingWidth:localFlag('readingWidth'),details:false,allLevels:false,view:'table',dbQuery:'',dbSort:'',dbDesc:false,dbMonth:new Date().toLocaleDateString('sv-SE').slice(0,7),dbGroup:'',dbDate:'',preview:false,stats:null,status:null,undo:[],redo:[],focusBlock:null,menu:null,busy:false,recordPeek:null,openTabs:[]};
